insert into public.exercise_translations_gymtrack (exercisedb_id, name_pt, instructions_pt) values
  ('b2Uoz54', 'Elevação frontal com barra', array['Fique em pé com os pés na largura dos ombros e segure uma barra à frente das coxas com as palmas das mãos viradas para baixo.', 'Mantenha os braços retos e levante a barra para frente e para cima até atingir o nível dos ombros.', 'Comece com uma carga gerenciável e uma pequena flexão nos cotovelos.', 'Levante os braços para frente até a altura dos ombros, mantendo as costelas para baixo e o tronco imóvel.', 'Pare perto da altura dos ombros em vez de encolher os ombros para levantar mais alto.', 'Abaixe os braços lentamente para as laterais sem balançar o peso.']),
  ('B3Rxp6L', 'Supino reto com halteres inclinado', array['Incline o banco a aproximadamente 45 graus.', 'Sente-se no banco com as costas apoiadas no encosto e os pés firmes no chão.', 'Contraia o tronco e alinhe os punhos com os antebraços.', 'Empurre o peso ou as alças para longe enquanto mantém o tronco contraído.', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural.', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente.']),
  ('b4b6afT', 'Rosca de bíceps sentada com peso (na bola suíça)', array['Sente-se em uma bola suíça com os pés firmes e as costas retas.', 'Pegue uma bola medicinal com as palmas das mãos viradas para cima e deixe os braços caírem ao lado do corpo.', 'Posicione os ombros e a parte superior dos braços antes de flexionar os cotovelos.', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco.', 'Mantenha a bola firme e use os pés para controlar o equilíbrio.', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços imóvel.']),
  ('b5uBMv2', 'Elevações de braço alternadas na bola de exercício', array['Sente-se na bola suíça com os pés firmes e as costas retas.', 'Pegue um haltere em cada mão com as palmas viradas para dentro e os braços estendidos ao lado do corpo.', 'Comece com uma carga gerenciável e uma pequena flexão nos cotovelos.', 'Levante os pesos para longe do tronco até a altura dos ombros, mantendo os cotovelos levemente flexionados.', 'Termine o movimento de um lado antes que o outro lado comece.', 'Abaixe os braços lentamente para as laterais sem balançar o peso; troque de lado quando a série exigir.']),
  ('B5xca8s', 'Toque no dedão do pé circular com as mãos entrelaçadas', array['Fique em pé com os pés na largura dos ombros e as mãos entrelaçadas na altura do peito.', 'Flexione levemente os joelhos e incline-se para frente a partir dos quadris, com a coluna firme.', 'Amacie os joelhos e deixe os quadris iniciarem a flexão.', 'Incline-se para frente a partir dos quadris e deixe as mãos irem em direção aos pés sem forçar o alcance.', 'Mantenha o movimento controlado em toda a amplitude.', 'Segure brevemente em uma profundidade confortável, depois suba estendendo os quadris.']),
  ('b63ZzGe', 'Agachamento sumô com suporte', array['Fique em pé com os pés na largura dos ombros, com os dedos apontando levemente para fora.', 'Use um suporte estável, como uma cadeira ou parede, para manter o equilíbrio.', 'Contraia o abdômen e distribua a pressão por todo o pé.', 'Flexione os quadris e os joelhos para abaixar, mantendo os pés apoiados no chão e os joelhos alinhados com os dedos dos pés.', 'Empurre para cima com o peito e os quadris subindo juntos; evite que os joelhos desabem para dentro.', 'Fique totalmente em pé, ajuste sua postura e respiração, depois comece a próxima descida.']),
  ('B6dAO1t', 'Rosca de punho sentada no Smith', array['Sente-se em um banco em frente a uma máquina Smith com os pés apoiados', 'Segure a barra com as palmas voltadas para cima, com as mãos na largura dos ombros', 'Mantenha os cotovelos relaxados para que os pequenos músculos da mão ou do antebraço assumam a carga', 'Movimente os punhos ou os dedos enquanto os antebraços permanecem apoiados e parados', 'Use uma amplitude pequena e suave sem balançar os cotovelos', 'Retorne devagar ao início sem deixar a carga escapar das suas mãos']),
  ('b6hQYMb', 'Rosca Scott na máquina', array['Ajuste o assento ao seu corpo e acomode-se na máquina', 'Posicione os braços no apoio e segure os puxadores com as palmas voltadas para cima', 'Apoie o braço que está trabalhando no Scott e deixe o cotovelo livre para dobrar', 'Flexione o peso enquanto seus braços permanecem em contato com o apoio', 'Mantenha o tronco firme e deixe a flexão do cotovelo levantar o peso', 'Desça até que os cotovelos estejam quase esticados, mantendo os braços parados']),
  ('b9kqlBy', 'Remada serrote alternada com kettlebell', array['Comece em posição de prancha alta com as mãos segurando os kettlebells e os pés na largura dos quadris', 'Contraia o core e mantenha seu corpo em linha reta da cabeça aos calcanhares', 'Estabilize o tronco e permita que os braços fiquem estendidos para a frente sem curvar excessivamente', 'Puxe os cotovelos para trás e traga a alça ou o peso em direção ao seu tronco', 'Termine o movimento de um lado antes que o outro lado comece', 'Estenda os braços para a frente novamente sem deixar o tronco inclinar; alterne os lados quando necessário']),
  ('BaE7O6U', 'Elevação de joelhos oblíqua na barra fixa', array['Suspenda-se em uma barra fixa com os braços esticados e as palmas voltadas para a frente', 'Contraia o core e levante os joelhos em direção ao peito, girando o tronco para o lado ao fazer isso', 'Contraia o abdômen e mantenha os ombros fixos no suporte', 'Levante as pernas contraindo o core e movimentando os quadris em vez de balançar', 'Desacelere as pernas antes que elas tirem a parte inferior das costas da posição correta', 'Desça as pernas devagar sem balançar ou perder a posição do tronco']),
  ('BbfB8Gb', 'Toque nos pés em pé', array['Fique em pé com os pés na largura dos ombros e os braços ao lado do corpo', 'Incline-se para a frente na cintura, com a coluna firme e os joelhos levemente flexionados', 'Entre na posição inicial e respire suavemente antes de aprofundar o movimento', 'Dobre o quadril para a frente e deixe suas mãos irem em direção aos pés sem forçar o alcance', 'Mantenha-se em um leve 3stretchtra em vez de puxar mais com impulso', 'Segure brevemente em uma profundidade confortável e depois suba estendendo os quadris']),
  ('bBi35y3', 'Desenvolvimento com halteres em pé alternado', array['Fique em pé com os pés na largura dos ombros, segurando um halter em cada mão na altura dos ombros com as palmas voltadas para a frente', 'Antes de se mover, empurre um halter para cima, estendendo totalmente o braço', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou os puxadores para longe enquanto mantém seu core contraído', 'Termine o movimento de um lado antes que o outro lado comece', 'Desça o peso até a altura inicial com controle antes de empurrar novamente; alterne os lados quando necessário']),
  ('bbLR7fB', 'Elevação de pernas deitada com elástico', array['Deite-se de costas com as pernas esticadas e os pés juntos', 'Coloque o elástico ao redor do arco dos pés e segure as pontas com as mãos', 'Contraia o abdômen e mantenha os ombros fixos no suporte', 'Levante as pernas contraindo o core e movimentando os quadris em vez de balançar', 'Controle o elástico na volta em vez de deixar que ele puxe você de forma brusca', 'Desça as pernas devagar sem balançar ou perder a posição do tronco']),
  ('BCGQ6J5', 'Rosca direta com pegada fechada no cabo', array['Conecte uma barra reta a uma polia baixa', 'Fique de frente para a máquina com os pés na largura dos ombros e os joelhos levemente flexionados', 'Posicione os ombros e os braços antes de dobrar os cotovelos', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco firme e deixe a flexão do cotovelo levantar o peso', 'Desça até que os cotovelos estejam quase esticados, mantendo os braços parados']),
  ('BCs0G2F', 'Elevação de pernas sentado com barra', array['Sente-se em um banco com as costas retas e segure uma barra sobre as coxas', 'Posicione as mãos nas laterais do banco para apoio', 'Contraia o abdômen e mantenha os ombros fixos no apoio', 'Eleve as pernas contraindo o tronco e movimentando os quadris em vez de balançar', 'Conclua o movimento de um lado antes de iniciar o outro', 'Abaixe as pernas lentamente sem balançar ou perder a posição do tronco e alterne os lados quando necessário']),
  ('BCUR88E', 'Extensão unilateral em pé com halter', array['Fique em pé com os pés na largura dos ombros, segurando um halter em uma das mãos', 'Antes de se mover, levante o halter acima da cabeça, estendendo totalmente o braço', 'Posicione os braços firmemente antes de estender os cotovelos', 'Mantenha os braços estáveis e estenda através dos cotovelos para mover o peso', 'Mantenha ambos os ombros nivelados e evite virar em direção ao braço em movimento', 'Dobre os cotovelos lentamente para retornar ao início da próxima repetição e alterne os lados quando necessário']),
  ('bd5b860', 'Rosca de punho com rolo', array['Conecte um peso a uma das pontas de uma corda ou barra', 'Segure a outra ponta da corda ou barra com as duas mãos e palmas voltadas para baixo', 'Mantenha os cotovelos relaxados para que os pequenos músculos da mão ou antebraço assumam a carga', 'Movimente-se através dos punhos ou dedos enquanto os antebraços permanecem apoiados e parados', 'Use uma amplitude pequena e suave sem balançar os cotovelos', 'Retorne suavemente ao início sem deixar a carga cair das mãos']),
  ('bdWcbaU', 'Agachamento frankenstein', array['Fique em pé com os pés na largura dos ombros e segure a barra à frente do corpo com os braços retos', 'Com as costas retas, abaixe o corpo dobrando os joelhos e quadris, como se estivesse sentando em uma cadeira', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Dobre os quadris e joelhos para abaixar, mantendo os pés apoiados e os joelhos alinhados com os dedos', 'Empurre para cima com o peito e os quadris subindo juntos, evitando que os joelhos fechem para dentro', 'Fique totalmente em pé, ajuste sua base e respiração, e então inicie a próxima descida']),
  ('BeReYBf', 'Barra fixa lateral', array['Fique em pé com os pés na largura dos ombros e os joelhos levemente flexionados', 'Segure a barra de puxada com as palmas voltadas para baixo e as mãos logo acima da largura dos ombros', 'Comece a partir de uma suspensão controlada com os ombros ativos e não relaxados', 'Puxe os cotovelos para baixo e aproxime a parte superior do peito da barra sem chutar as pernas', 'Evite balançar as pernas para ultrapassar a barra', 'Abaixe até esticar os braços sem despencar do topo']),
  ('bfiHMpI', 'Supino inclinado com halter na bola suíça', array['Sente-se em uma bola suíça segurando um halter em cada mão com as palmas voltadas para a frente', 'Caminhe com os pés para a frente de forma controlada, rolando o corpo pela bola até que sua cabeça, pescoço e parte superior das costas estejam apoiados', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou as alças para longe mantendo o tronco contraído', 'Mantenha a bola estável e use os pés para controlar seu equilíbrio', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente']),
  ('Bg5JKSH', 'Supino inclinado unilateral com halter na bola suíça', array['Sente-se em uma bola suíça segurando um halter em uma das mãos e com os pés firmes no chão', 'Caminhe com os pés para a frente de forma controlada, rolando a bola até que sua cabeça, pescoço e parte superior das costas estejam apoiados', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso para longe mantendo o tronco contraído', 'Mantenha ambos os ombros nivelados e evite virar em direção ao braço em movimento', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente e alterne os lados quando necessário']),
  ('BgljGjd', 'Remada cavalinho na máquina', array['Ajuste a altura do assento e a posição do apoio para os pés na máquina', 'Sente-se na máquina com o peito contra o apoio e os pés apoiados na plataforma', 'Posicione o tronco e permita que os quais os braços se estendam para a frente sem curvar excessivamente', 'Puxe os cotovelos para trás e aproxime a alça ou o peso do tronco', 'Traga os cotovelos para trás sem dar trancos com o tronco', 'Estenda os braços para a frente novamente sem deixar o tronco inclinar bruscamente']),
  ('BIb1tGo', 'Rosca concentrada com halter em pé (sobre banco inclinado)', array['Fique em pé e posicione os pés na largura dos ombros, segurando um halter em uma mão com a palma virada para frente', 'Apoie a outra mão em um banco inclinado para suporte', 'Estabilize os ombros e a parte superior dos braços antes de flexionar os cotovelos', 'Flexione os cotovelos para levar o peso em direção aos ombros sem balançar o tronco', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço que está trabalhando', 'Abaixe até que os cotovelos estejam quase esticados, mantendo a parte superior dos braços parada; alterne os lados quando necessário']),
  ('BJ0Hz5L', 'Remada curvada com halteres', array['Fique em pé com os pés na largura dos ombros, joelhos levemente flexionados, e segure um halter em cada mão com as palmas voltadas para o corpo', 'Incline-se para frente a partir do quadril, com a coluna firme e o core contraído', 'Estabilize o tronco e deixe os braços esticados para frente sem curvar excessivamente as costas', 'Puxe os cotovelos para trás e leve o peso em direção ao tronco', 'Traga os cotovelos para trás sem dar trancos no tronco', 'Estenda os braços para frente novamente sem deixar o tronco balançar']),
  ('bjqbauy', 'Aperto de mãos em pé com peso', array['Fique em pé com os pés na largura dos ombros e segure um peso em cada mão', 'Estenda os braços retos na sua frente, com as palmas voltadas uma para a outra', 'Mantenha os cotovelos relaxados para que os pequenos músculos da mão ou do antebraço recebam a carga', 'Movimente os punhos ou dedos enquanto os antebraços permanecem apoiados e parados', 'Use uma amplitude pequena e suave sem balançar os cotovelos', 'Retorne ao início com cuidado sem deixar a carga cair das mãos']),
  ('bJYHBIN', 'Elevação de panturrilha em pé com peso corporal', array['Fique em pé com os pés na largura dos ombros e pontas dos pés voltadas para frente', 'Apoie as mãos em uma parede ou superfície estável para manter o equilíbrio', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece firme', 'Suba na ponta dos pés, elevando os calcanhares o mais alto possível sem balançar', 'Faça uma pausa no topo sem girar os tornozelos para fora', 'Abaixe os calcanhares em um ritmo controlado antes de subir novamente']),
  ('BKa8dmT', 'Rosca de punho neutra com halter sobre o banco', array['Apoie ambos os pés no chão sentado em um banco; segure um halter em cada mão com as palmas viradas para cima', 'Apoie os antebraços no banco deixando os punhos livres além da borda', 'Mantenha os cotovelos relaxados para que os pequenos músculos da mão ou do antebraço recebam a carga', 'Movimente os punhos ou dedos enquanto os antebraços permanecem apoiados e parados', 'Use uma amplitude pequena e suave sem balançar os cotovelos', 'Retorne ao início com cuidado sem deixar a carga cair das mãos']),
  ('bKWbrTA', 'Remada com toalha unilateral', array['Fique em pé com os pés na largura dos ombros, joelhos levemente flexionados, e segure uma toalha com uma mão', 'Incline-se para frente a partir da cintura, com a coluna firme e o core contraído', 'Estabilize o tronco e deixe os braços esticados para frente sem curvar excessivamente as costas', 'Puxe os cotovelos para trás e leve a alça ou o peso em direção ao tronco', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço que está trabalhando', 'Estenda os braços para frente novamente sem deixar o tronco balançar; alterne os lados quando necessário']),
  ('BkxB8LW', 'Desenvolvimento sentado com kettlebell', array['Sente-se em um banco com as costas retas e os pés apoiados no chão', 'Segure um kettlebell em cada mão na altura dos ombros, com as palmas voltadas para frente', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso para cima mantendo o tronco firme', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente']),
  ('BL3GHeY', 'Planche aberta', array['Comece em posição de flexão com as mãos na largura dos ombros e os pés bem afastados', 'Contraia o tronco e, com controle, desloque seu peso para frente, trazendo os ombros sobre as mãos', 'Contraia o abdômen e encontre uma posição que consiga manter sem prender a respiração', 'Contraia o abdômen e mantenha a posição respirando normalmente', 'Continue respirando de forma constante enquanto mantém a mesma linha corporal', 'Mantenha a postura pelo tempo planejado e depois saia dela com controle']),
  ('blBXysN', 'Desenvolvimento militar com dois kettlebells', array['Fique de pé com os pés na largura dos ombros, segurando um kettlebell em cada mão na altura dos ombros com as palmas voltadas para a frente', 'Contraia o abdômen e empurre os kettlebells para cima da cabeça, estendendo os braços', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou as alças para longe mantendo o tronco contraído', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente']),
  ('BLCvwr2', 'Rosca inversa de punho com halter', array['Sente-se em um banco ou cadeira com os pés apoiados', 'Segure um halter em cada mão com as palmas voltadas para baixo', 'Mantenha os cotovelos relaxados para que os pequenos músculos da mão ou do antebraço suportem a carga', 'Movimente os punhos ou dedos enquanto os antebraços permanecem apoiados e imóveis', 'Use uma amplitude pequena e suave sem balançar os cotovelos', 'Retorne ao início sem deixar a carga escapar das mãos']),
  ('bLyQokI', 'London bridge', array['Conecte a corda a um ponto de ancoragem alto', 'Fique de costas para o ponto de ancoragem em uma base estável com os pés na largura dos ombros', 'Posicione o tronco e permita que os braços se estendam para a frente sem curvar excessivamente', 'Puxe os cotovelos para trás e traga a alça ou o peso em direção ao tronco', 'Traga os cotovelos para trás sem dar trancos no tronco', 'Estenda os braços para a frente novamente sem deixar o tronco oscilar']),
  ('bmBf7LN', 'Rotação externa de ombro deitado com halter', array['Deite-se de lado em um banco plano com o braço junto ao corpo e o cotovelo flexionado a 90 graus', 'Segure um halter na mão com a palma voltada para baixo', 'Posicione a pelve e realize a rotação através da caixa torácica', 'Gire através do tronco enquanto os quadris e a parte inferior do corpo permanecem o mais firmes possível', 'Mantenha o giro suave em vez de lançar os braços através do corpo', 'Retorne pelo centro antes de virar para o outro lado']),
  ('BMMolZ3', 'Abdominal tuck crunch', array['Deite-se de costas com os joelhos flexionados e os pés apoiados', 'Coloque as mãos atrás da cabeça com os cotovelos apontados para fora', 'Posicione a pelve e mantenha o pescoço relaxado antes de flexionar para cima', 'Flexione a caixa torácica em direção à pelve, permitindo que o abdômen movimente o tronco', 'Deixe um pequeno espaço entre o queixo e o peito; mantenha o movimento no tronco', 'Abaixe os ombros ou o tronco com controle antes da próxima flexão']),
  ('BmrwWzo', 'Pull through sumô com halter', array['Fique de pé com os pés mais afastados que a largura dos ombros e as pontas dos pés voltadas para fora', 'Segure um halter com ambas as mãos à frente do corpo, com os braços estendidos', 'Destrave os joelhos e contraia o abdômen antes de mover os quadris para trás', 'Empurre os quadris para trás mantendo a carga próxima e a coluna firme', 'Mantenha o peso próximo às pernas e pare quando as costas começarem a curvar', 'Projete os quadris para frente para ficar ereto sem inclinar para trás no topo']),
  ('bmwlYvD', 'Barra fixa supinada', array['Fique de pé com os pés na largura dos ombros e os joelhos flexionados', 'Segure a barra de pull-up com as palmas voltadas para baixo, logo além da largura dos ombros', 'Comece de uma suspensão controlada com os ombros ativos em vez de relaxados', 'Puxe os cotovelos para baixo e traga a parte superior do peito em direção à barra sem chutar as pernas', 'Evite balançar as pernas para passar da barra', 'Desça até estender os braços sem cair repentinamente do topo']),
  ('Bn6TXyO', 'Abdominal remador', array['Deite-se de costas com os joelhos flexionados e os pés apoiados', 'Coloque as mãos atrás da cabeça com os cotovelos apontados para fora', 'Posicione a pelve e mantenha o pescoço relaxado antes de flexionar para cima', 'Flexione a caixa torácica em direção à pelve, permitindo que o abdômen movimente o tronco', 'Deixe um pequeno espaço entre o queixo e o peito; mantenha o movimento no tronco', 'Abaixe os ombros ou o tronco com controle antes da próxima flexão']),
  ('bndCa3Q', 'Supino com barra nos pinos', array['Prepare uma barra em um suporte de agachamento na altura do peito.', 'Fique de frente para a barra e posicione-se embaixo dela, com uma base estável e pés na largura dos ombros.', 'Contraia o tronco e alinhe os punhos com os antebraços.', 'Empurre o peso ou pegas enquanto mantém o tronco contraído.', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural.', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente.']),
  ('bOOdeyc', 'Elevação de panturrilha sentada na máquina', array['Ajuste a altura do assento para que seus joelhos fiquem levemente flexionados e seus pés apoiados na plataforma.', 'Posicione as pontas dos pés na plataforma com os calcanhares para fora da borda.', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece firme.', 'Suba na ponta dos pés, elevando os calcanhares o mais alto possível sem balançar.', 'Faça uma pausa no topo sem girar os tornozelos para fora.', 'Abaixe os calcanhares em ritmo controlado antes de subir novamente.']),
  ('bpJL2Qs', 'Extensão de tríceps com halteres e pegada pronada', array['Sente-se em um banco ou cadeira com as costas retas e os pés apoiados.', 'Pegue um halter com as duas mãos, palmas viradas para baixo, e estique os braços diretamente para cima.', 'Posicione os braços firmemente antes de estender os cotovelos.', 'Mantenha os braços firmes e estenda os cotovelos para mover o peso.', 'Mantenha os braços firmes enquanto os antebraços se movimentam.', 'Dobre os cotovelos lentamente para retornar ao início da próxima repetição.']),
  ('Bpkf41o', 'Crucifixo com halter unilateral na bola suíça', array['Sente-se em uma bola suíça com um halter em uma mão e os pés apoiados.', 'Dê um passo à frente, rolando a bola até que sua parte superior das costas esteja apoiada na bola e sua cabeça, pescoço e ombros fiquem fora dela.', 'Mantenha uma leve flexão nos cotovelos e ajuste os ombros antes de mover os braços.', 'Com uma leve flexão nos cotovelos, junte os braços em um arco largo.', 'Mantenha ambos os ombros nivelados e evite girar o tronco para o lado do braço em movimento.', 'Abra os braços de volta pelo mesmo arco sem deixar o peso cair; alterne os lados quando necessário.']),
  ('BqgCRif', 'Desenvolvimento cubano com halteres', array['Fique em pé com os pés na largura dos ombros, segurando um halter em cada mão na altura dos ombros com as palmas viradas para baixo.', 'Com o abdômen contraído e as costas retas, empurre os halteres diretamente para cima até que seus braços estejam esticados.', 'Contraia o tronco e alinhe os punhos com os antebraços.', 'Empurre o peso ou pegas enquanto mantém o tronco contraído.', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural.', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente.']),
  ('bQHPBU3', 'Pull-over com halter unilateral na bola suíça', array['Sente-se em uma bola suíça com os pés apoiados e os joelhos flexionados a 90 graus.', 'Pegue um halter com uma mão e estique o braço para cima acima do peito.', 'Abaixe as costelas e mantenha uma leve flexão no cotovelo antes de abaixar o peso.', 'Abaixe o peso em arco atrás da cabeça até sentir um alongamento confortável no ombro.', 'Mantenha ambos os ombros nivelados e evite girar o tronco para o lado do braço em movimento.', 'Puxe o peso de volta sobre o peito pelo mesmo arco, sem levantar as costelas; alterne os lados quando necessário.']),
  ('bQy2Eni', 'Tríceps coice com halter unilateral', array['Fique em pé com os pés na largura dos ombros e segure um halter na mão direita.', 'Flexione levemente os joelhos e incline o tronco à frente a partir do quadril, mantendo a coluna firme.', 'Posicione o braço firmemente antes de estender o cotovelo.', 'Mantenha a parte superior do braço ao lado do tronco e estique o cotovelo para trás.', 'Mantenha ambos os ombros nivelados e evite girar o tronco para o lado do braço em movimento.', 'Dobre o cotovelo lentamente para retornar ao início da próxima repetição; alterne os lados quando necessário.']),
  ('BReCuOn', 'Remada com agachamento usando peso corporal (com toalha)', array['Fique em pé com os pés na largura dos ombros, segurando uma toalha à sua frente com as palmas viradas para baixo.', 'Flexione os joelhos e abaixe o corpo em posição de agachamento, mantendo a coluna firme e o peito estufado.', 'Contraia o abdômen e distribua a pressão por todo o pé.', 'Flexione o quadril e os joelhos para descer, mantendo os pés apoiados e os joelhos alinhados com os dedos dos pés.', 'Empurre para cima elevando o peito e o quadril juntos; evite que os joelhos caiam para dentro.', 'Fique totalmente em pé, ajuste sua postura e respiração, e então inicie a próxima descida.']),
  ('BRImeP8', 'Tríceps sentado na máquina', array['Ajuste a altura do assento para que seus pés fiquem apoiados no chão e seus joelhos em um ângulo de 90 graus.', 'Segure os puxadores da máquina com as palmas para baixo e os braços esticados.', 'Mantenha os ombros para baixo e os cotovelos apontados principalmente para trás.', 'Dobre os cotovelos para abaixar entre os suportes; pare em uma profundidade confortável para os ombros.', 'Escolha uma profundidade que permita manter os ombros confortáveis.', 'Empurre pelas mãos para subir, depois ajuste os ombros antes de outra repetição.']),
  ('bRlbdjK', 'Encolhimento declinado com halteres', array['Prepare um banco declinado a um ângulo de 45 graus.', 'Posicione-se de bruços no banco com o peito e o abdômen apoiados nele.', 'Deixe os braços soltos e mantenha a cabeça neutra.', 'Eleve os ombros em direção às orelhas sem dobrar os cotovelos ou girar os ombros.', 'Suba e desça verticalmente sem fazer círculos com os ombros.', 'Retorne o peso ou o corpo à posição inicial sem pressa.']),
  ('bTpEUcm', 'Agachamento com barra baixa', array['Fique de pé com os pés na largura dos ombros e a barra apoiada na parte superior das costas.', 'Com o peito estufado e o core contraído, abaixe o corpo de forma controlada dobrando os joelhos e empurrando o quadril para trás.', 'Contraia o abdômen e distribua a pressão por todo o pé.', 'Dobre o quadril e os joelhos para descer, mantendo os pés firmes no chão e os joelhos alinhados com os dedos dos pés.', 'Empurre para cima subindo o peito e o quadril juntos; evite que os joelhos virem para dentro.', 'Fique totalmente em pé, ajuste sua base e respiração, então inicie a próxima descida.']),
  ('BU15nH4', 'Rosca bicep alternada com halteres', array['Fique em pé com um halter em cada mão, palmas viradas para a frente e braços esticados.', 'Com a parte superior dos braços parada, expire e flexione os pesos enquanto contrai os bíceps.', 'Posicione os ombros e a parte superior dos braços antes de dobrar os cotovelos.', 'Dobre os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco.', 'Termine o movimento de um lado antes que o outro lado comece.', 'Abaixe até que os cotovelos estejam quase esticados, mantendo a parte superior dos braços parada; mude de lado quando o exercício exigir.']),
  ('bWlZvXh', 'Postura de ioga da borboleta', array['Sente-se no chão com as pernas estendidas à sua frente.', 'Dobre os joelhos e junte as solas dos pés, deixando os joelhos caírem para os lados.', 'Acomode-se na posição inicial e respire calmamente antes de aprofundar o movimento.', 'Aproximar-se do alongamento suavemente até sentir uma leve tensão; continue respirando e evite balançar.', 'Mantenha um alongamento leve em vez de puxar mais com impulso.', 'Mantenha a posição com respiração constante e solte devagar; repita do outro lado se necessário.']),
  ('BWnJR72', 'Alongamento de quadríceps deitado de lado', array['Deite-se de lado com as pernas esticadas.', 'Antes de se mover, dobre a perna de cima e segure o tornozelo ou o pé com a mão.', 'Acomode-se na posição inicial e respire calmamente antes de aprofundar o movimento.', 'Aproximar-se do alongamento suavemente até sentir uma leve tensão; continue respirando e evite balançar.', 'Mantenha um alongamento leve em vez de puxar mais com impulso.', 'Mantenha a posição com respiração constante e solte devagar; repita do outro lado se necessário.']),
  ('BwSNDGt', 'Rosca de punho reversa unilateral com halter', array['Sente-se em um banco ou cadeira com os pés apoiados.', 'Pegue um halter com uma mão com a palma virada para baixo, palma virada para baixo.', 'Mantenha os cotovelos relaxados para que os pequenos músculos da mão ou do antebraço suportem a carga.', 'Movimente os punhos ou dedos enquanto os antebraços permanecem apoiados e parados.', 'Mantenha ambos os ombros nivelados e evite virar o corpo para o braço que está trabalhando.', 'Retorne suavemente ao início sem deixar a carga cair das mãos; mude de lado quando o exercício exigir.']),
  ('bWxq4op', 'Rosca direta scott reversa unilateral com halter', array['Sente-se em um banco scott com o peito apoiado no encosto e o braço estendido sobre a borda do banco, segurando um halter com as palmas para cima.', 'Abaixe o halter de forma controlada até que seu braço esteja esticado.', 'Apoie a parte superior do braço que está trabalhando no encosto do banco scott e deixe o cotovelo livre para dobrar.', 'Flexione o peso enquanto a parte superior dos braços permanece em contato com o encosto.', 'Mantenha ambos os ombros nivelados e evite virar o corpo para o braço que está trabalhando.', 'Abaixe até que os cotovelos estejam quase esticados, mantendo a parte superior dos braços parada; mude de lado quando o exercício exigir.']),
  ('ByX0WxV', 'Rosca martelo inclinada com halteres', array['Sente-se em um banco inclinado com um halter em cada mão, palmas viradas para o seu tronco e braços esticados.', 'Mantenha suas costas contra o banco e os pés apoiados.', 'Encaixe os ombros e a parte superior dos braços antes de flexionar os cotovelos.', 'Faça a rosca com as palmas viradas uma para a outra e os cotovelos próximos às laterais do corpo; evite balançar para trás.', 'Mantenha as palmas viradas uma para a outra e os pulsos retos.', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços imóvel.']),
  ('bZGHsAZ', 'Remada invertida', array['Prepare uma barra na altura da cintura ou use um equipamento de suspensão.', 'Fique de frente para a barra ou equipamento de suspensão, com uma base estável e pés na largura dos ombros.', 'Posicione o tronco e permita que os braços se estendam para a frente sem curvar excessivamente.', 'Puxe os cotovelos para trás e traga a manopla ou peso em direção ao seu tronco.', 'Traga os cotovelos para trás sem sacudir o tronco.', 'Estenda os braços para a frente novamente sem deixar o tronco dar trancos.']),
  ('bZq4bwK', 'Mergulho em paralela com peso', array['Sente-se na borda de um banco ou cadeira com as mãos segurando a borda ao lado dos quadris.', 'Afaste o quadril da frente do banco com as pernas estendidas à sua frente.', 'Posicione os ombros para baixo e mantenha os cotovelos apontados principalmente para trás.', 'Flexione os cotovelos para descer entre os apoios; pare em uma profundidade confortável para os ombros.', 'Escolha uma profundidade que permita que os ombros fiquem confortáveis.', 'Pressione com as mãos para subir, depois ajuste os ombros antes de outra repetição.']),
  ('C0eCeEt', 'Elevação de pernas torcida', array['Deite-se de costas com as pernas estendidas e os braços ao lado do corpo.', 'Posicione as mãos sob os glúteos para suporte.', 'Contraia o abdômen e mantenha os ombros ancorados ao suporte.', 'Eleve as pernas contraindo o tronco e movimentando nos quadris em vez de balançar.', 'Desacelere as pernas antes que elas tirem a parte inferior das costas da posição.', 'Abaixe as pernas lentamente sem balançar ou perder a posição do tronco.']),
  ('C0MA9bC', 'Remada curvada unilateral com halter', array['Fique em pé e posicione os pés na largura dos ombros, segurando um halter em uma mão com a palma virada para o corpo.', 'Flexione os joelhos levemente e incline-se para a frente nos quadris, com a coluna firme e o core ativado.', 'Posicione o tronco e permita que os braços se estendam para a frente sem curvar excessivamente.', 'Puxe os cotovelos para trás e traga a manopla ou peso em direção ao seu tronco.', 'Mantenha ambos os ombros nivelados e resista a girar em direção ao braço que está trabalhando.', 'Estenda os braços para a frente novamente sem deixar o tronco dar trancos; alterne os lados quando a série exigir.']),
  ('c16nYGA', 'Supino com rotação no cabo unilateral', array['Conecte o elástico a um ponto de ancoragem firme na altura do peito.', 'Fique em pé com a lateral voltada para o ponto de ancoragem e segure o elástico com uma mão.', 'Contraia o tronco e alinhe os pulsos com os antebraços.', 'Empurre os pesos para cima enquanto vira as palmas para dentro; inverta a rotação ao abaixar.', 'Mantenha ambos os ombros nivelados e resista a girar em direção ao braço que está trabalhando.', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente; alterne os lados quando a série exigir.']),
  ('C31LMnP', 'Agachamento unilateral', array['Fique em pé e posicione os pés na largura dos ombros.', 'Estenda uma perna para a frente, mantendo-a fora do chão.', 'Contraia o abdômen e distribua a pressão por todo o pé.', 'Flexione nos quadris e joelhos para descer, mantendo os pés apoiados no chão e os joelhos alinhados com os dedos dos pés.', 'Mantenha a pelve nivelada enquanto a perna de apoio faz o trabalho.', 'Fique totalmente em pé, ajuste sua base e respiração, depois inicie a próxima descida; alterne os lados quando a série exigir.']),
  ('c3Pfhti', 'Alongamento lateral de grandes dorsais com rolo', array['Fique em pé e posicione os pés na largura dos ombros, segurando o rolo com ambas as mãos à frente do corpo.', 'Flexione os joelhos levemente e incline-se para a frente nos quadris, com a coluna firme.', 'Entre na posição inicial e respire calmamente antes de aprofundar o movimento.', 'Vá em direção ao alongamento até sentir uma tensão leve; continue respirando e evite balançar.', 'Permaneça em um alongamento leve em vez de puxar mais com impulso.', 'Mantenha a posição com respiração constante, depois solte suavemente; repita do outro lado, se necessário.']),
  ('c3QQLPi', 'Remada alta no cabo com corda', array['Conecte uma alça a uma polia baixa e fique de costas para a máquina', 'Segure a alça com as palmas para baixo e estique os braços para a frente', 'Posicione os braços antes de estender os cotovelos', 'Mantenha os braços firmes e estenda pelos cotovelos para mover o peso', 'Mantenha os braços firmes enquanto os antebraços se movimentam', 'Flexione os cotovelos devagar para retornar ao início da próxima repetição']),
  ('C5jncD2', 'Flexão de perna em pé unilateral', array['Fique em pé com os pés na largura dos quadris e as mãos na cintura', 'Transfira o peso para a perna esquerda e tire o pé direito do chão, flexionando o joelho', 'Alinhe os joelhos com a máquina ou borda do banco antes de iniciar a flexão', 'Flexione os joelhos para puxar o apoio na sua direção sem levantar os quadris do suporte', 'Mantenha os quadris parados enquanto os joelhos flexionam', 'Retorne suavemente ao início antes de repetir']),
  ('C8Crfa4', 'Supino fechado no Smith', array['Ajuste o assento ao seu corpo e acomode-se na máquina', 'Segure a barra com pegada fechada, um pouco mais estreita que a largura dos ombros', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou as alças para longe mantendo o tronco contraído', 'Mantenha os punhos alinhados e use uma trajetória de ombro natural', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente']),
  ('c8f5cSY', 'Adução de quadril deitada de lado', array['Deite-se de lado com as pernas esticadas e empilhadas uma sobre a outra', 'Apoie o braço de baixo sob a cabeça para suporte', 'Nivele a pelve antes de mover a perna de trabalho', 'Puxe a perna de trabalho para dentro contra a resistência sem inclinar para o lado', 'Movimente apenas até onde a pelve puder permanecer firme', 'Traga o peso ou corpo de volta à posição inicial sem pressa']),
  ('c8oybX6', 'Remada sentada elevada com corda no cabo', array['Sente-se no assento elevado de frente para a máquina de cabo', 'Segure uma ponta da corda em cada mão com as palmas voltadas uma para a outra', 'Posicione o tronco e permita que os braços se estendam para a frente sem arredondar excessivamente', 'Puxe os cotovelos para trás e traga a alça ou peso em direção ao tronco', 'Traga os cotovelos para trás sem tranco no tronco', 'Estenda os braços para a frente novamente sem deixar o tronco oscilar']),
  ('C9LuR4A', 'Elevação de panturrilha em pé tipo Donkey', array['Ajuste a máquina de alavanca para a altura adequada ao seu corpo', 'Posicione-se de frente para a máquina, com as pontas dos pés na plataforma e os calcanhares para fora da borda', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece parado', 'Suba na ponta dos pés, elevando os calcanhares o máximo possível sem balançar', 'Faça uma pausa no topo sem girar os tornozelos para fora', 'Abaixe os calcanhares em ritmo cadenciado antes de subir novamente']),
  ('c9MnDRp', 'Elevação com halteres', array['Fique em pé com os pés na largura dos ombros e segure um halter em cada mão, com as palmas voltadas para o corpo', 'Mantenha a coluna em uma posição neutra e confortável e contraia o tronco', 'Comece com uma carga moderada e uma pequena flexão nos cotovelos', 'Eleve os pesos para longe do tronco até a altura dos ombros, mantendo os cotovelos levemente flexionados', 'Pare perto da altura dos ombros em vez de encolher os ombros para subir mais', 'Abaixe os braços devagar para as laterais sem balançar o peso']),
  ('Ca76jUE', 'Remada alternada com kettlebell', array['Fique em pé com os pés na largura dos ombros, joelhos levemente flexionados e segure um kettlebell em cada mão com as palmas voltadas para o corpo', 'Incline-se para a frente a partir dos quadris, com a coluna firme e o core ativado', 'Posicione o tronco e permita que os braços se estendam para a frente sem arredondar excessivamente', 'Puxe os cotovelos para trás e traga a alça ou peso em direção ao tronco', 'Finalize o movimento de um lado antes que o outro lado comece', 'Estenda os braços para a frente novamente sem deixar o tronco oscilar; alterne os lados quando a série exigir']),
  ('cA9FuWG', 'Pullover com barra', array['Deite-se em um banco com a cabeça em uma ponta e os pés no chão.', 'Segure uma barra com pegada na largura dos ombros e estenda os braços retos acima do peito.', 'Encaixe as costelas e mantenha uma pequena flexão nos cotovelos antes de descer o peso.', 'Desça o peso em um arco atrás da cabeça até sentir um alongamento confortável nos ombros.', 'Mantenha as costelas encaixadas enquanto os braços passam por cima da cabeça.', 'Puxe o peso de volta sobre o peito pelo mesmo arco, sem levantar as costelas.']),
  ('cALkHHX', 'Crucifixo inverso com halteres', array['Fique em pé com os pés na largura dos ombros, segurando um halter em cada mão ao lado do corpo.', 'Antes de mover, eleve os braços para os lados até ficarem paralelos ao chão, formando um T com o corpo.', 'Comece com uma carga gerenciável e uma pequena flexão nos cotovelos.', 'Abra os braços para os lados para formar um T e retorne-os sob controle.', 'Pare perto da altura dos ombros em vez de encolher para subir mais alto.', 'Desça os braços lentamente para os lados sem balançar o peso.']),
  ('cALKspW', 'Remada alta no cabo', array['Fique em pé com os pés na largura dos ombros, joelhos semiflexionados e segure o puxador do cabo com as palmas para baixo.', 'Mantenha a coluna em uma posição neutra confortável e o core contraído durante o exercício.', 'Posicione o tronco e permita que os braços avancem sem arredondar excessivamente.', 'Puxe os cotovelos para trás e traga o puxador ou peso em direção ao tronco.', 'Traga os cotovelos para trás sem dar trancos com o tronco.', 'Estenda os braços para a frente novamente sem deixar o tronco balançar.']),
  ('cAvTaSg', 'Tríceps coice na bola suíça', array['Sente-se em uma bola suíça com os pés apoiados e as costas retas.', 'Segure um halter em cada mão com as palmas voltadas para dentro e os braços flexionados a 90 graus.', 'Posicione os braços firmes antes de estender os cotovelos.', 'Mantenha a parte superior do braço ao lado do tronco e estique o cotovelo para trás.', 'Mantenha a bola firme e use os pés para controlar o equilíbrio.', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição.']),
  ('CB8WET1', 'Flexão inclinada', array['Escolha uma superfície elevada, como um banco ou degrau, e coloque as mãos na largura dos ombros na borda.', 'Afaste os pés para trás, mantendo o corpo em linha reta da cabeça aos calcanhares.', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos.', 'Flexione os cotovelos para abaixar o peito enquanto mantém o corpo em linha reta.', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos flexionam.', 'Empurre de volta para os braços estendidos, mantendo a linha do corpo intacta.']),
  ('CbFSYC1', 'Puxada supinada', array['Segure a barra de puxada com as palmas para baixo, logo além da largura dos ombros.', 'Suspenda-se na barra com os braços retos e o corpo reto.', 'Comece de uma suspensão controlada com os ombros ativos em vez de relaxados.', 'Puxe com controle, mantendo a cabeça neutra e os cotovelos descendo ao lado do tronco.', 'Evite balançar as pernas para passar da barra.', 'Desça com os braços estendidos sem despencar do topo.']),
  ('cbuFJrn', 'Encolhimento de ombros na máquina', array['Ajuste o assento ao seu corpo e acomode-se na máquina.', 'Segure as manoplas ou barras com as palmas para baixo, mantendo os braços estendidos.', 'Deixe os braços compridos pendurados e mantenha a cabeça neutra.', 'Eleve os ombros em direção às orelhas sem flexionar os cotovelos ou girar os ombros.', 'Eleve e abaixe verticalmente sem girar os ombros.', 'Retorne suavemente ao início antes de repetir.']),
  ('CcWEoWV', 'Corrida de passada curta', array['Escolha um espaço aberto ou uma esteira para realizar o exercício.', 'Fique erguido e posicione os pés na largura dos quadris.', 'Comece em um ritmo que permita que os pés e os braços se movam em sincronia.', 'Mova-se em um ritmo repetível, mantendo o movimento suave e a respiração constante.', 'Mantenha o padrão repetível conforme a velocidade aumenta.', 'Mantenha o ritmo pelo intervalo planejado, diminuindo a velocidade se a forma começar a falhar.']),
  ('CfKsRbG', 'Rosca alternada com halteres (com arm blaster)', array['Fique em pé com os pés na largura dos ombros e segure um halter em cada mão com as palmas voltadas para frente', 'Posicione o arm blaster nos braços, garantindo um ajuste seguro', 'Encaixe os ombros e os braços antes de flexionar os cotovelos', 'Flexione os cotovelos para levar o peso em direção aos ombros sem balançar o tronco', 'Termine o movimento de um lado antes de iniciar o outro', 'Desça até que os cotovelos estejam quase retos, mantendo os braços parados; alterne os lados quando necessário']),
  ('CFN9P8G', 'Tríceps francês com barra EZ na bola suíça', array['Sente-se em uma bola suíça e segure uma barra EZ com as palmas voltadas para baixo', 'Estique os braços para cima, mantendo os cotovelos próximos à cabeça', 'Posicione os braços firmemente antes de estender os cotovelos', 'Flexione os cotovelos para descer a barra atrás da cabeça enquanto os braços permanecem quase parados', 'Mantenha a bola estável e use os pés para controlar o equilíbrio', 'Estique os cotovelos para levar a barra acima da cabeça, depois inicie a próxima repetição controlada']),
