  ('dFSNDOA', 'Rotação sentada com barra', array['Sente-se em um banco reto com os pés apoiados e os joelhos flexionados', 'Segure uma barra com as duas mãos na frente do peito, mantendo os cotovelos semiflexionados', 'Ajuste a pelve e faça a rotação através da caixa torácica', 'Gire o tronco enquanto o quadril e a parte inferior do corpo permanecem o mais firmes possível', 'Mantenha a rotação fluida em vez de jogar os braços através do corpo', 'Retorne ao centro antes de girar para o outro lado']),
  ('dG5Smob', 'Puxada alta de arranco', array['Fique em pé com os pés na largura dos ombros e a barra no chão à sua frente', 'Flexione os joelhos e incline o quadril para agachar, segurando a barra com as palmas voltadas para baixo', 'Contraia o abdômen antes da puxada e mantenha a carga próxima ao corpo', 'Empurre com as pernas e o quadril, depois conduza o peso para a posição de recepção', 'Receba a carga com o tronco firme e os pés estáveis', 'Fique em pé para finalizar, depois baixe o peso com controle antes da próxima repetição']),
  ('dG7tG5y', 'Encolhimento de ombros com barra', array['Fique em pé com os pés na largura dos ombros e segure uma barra na frente com as palmas voltadas para baixo', 'Mantenha os braços estendidos e a coluna firme durante todo o exercício', 'Deixe os braços longos e mantenha a cabeça neutra', 'Eleve os ombros em direção às orelhas sem flexionar os cotovelos ou girar os ombros', 'Suba e desça verticalmente sem fazer círculos com os ombros', 'Retorne à posição inicial antes de repetir']),
  ('DgZQ11d', 'Press facial declinado com pegada fechada na barra EZ', array['Posicione-se em um banco declinado com a cabeça mais baixa que os pés', 'Segure a barra EZ com pegada fechada e palmas voltadas uma para a outra', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou os puxadores para longe enquanto mantém o tronco firme', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural', 'Desça o peso até a altura inicial com controle antes de empurrar novamente']),
  ('DhMl549', 'Agachamento livre completo com barra', array['Fique em pé com os pés na largura dos ombros e pontas dos pés levemente viradas para fora', 'Apoie a barra na parte superior das costas e segure firmemente', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione o quadril e os joelhos para descer, mantendo os pés apoiados e os joelhos alinhados com os dedos', 'Suba empurrando com o peito e o quadril subindo juntos; evite que os joelhos desabem para dentro', 'Fique totalmente em pé, ajuste a base e a respiração, depois inicie a próxima descida']),
  ('DICPHtq', 'Elevação de panturrilha unilateral', array['Fique em pé com os pés na largura do quadril e segure um halter em uma das mãos', 'Antes de se mover, tire um pé do chão e equilibre-se no outro pé', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo fica imóvel', 'Suba na ponta dos pés, elevando os calcanhares o mais alto possível sem balançar', 'Faça uma pausa no topo sem girar os tornozelos para fora', 'Abaixe os calcanhares em ritmo controlado antes de subir novamente']),
  ('DIVyqrU', 'Esfinge', array['Posicione-se de barriga para baixo no chão com os antebraços apoiados no piso e cotovelos diretamente sob os ombros', 'Contraia o tronco e levante o peito do chão, mantendo os antebraços e as pontas dos pés no piso', 'Acomode-se na posição inicial e respire calmamente antes de aprofundar o movimento', 'Vá em direção ao alongamento até sentir uma tensão leve; continue respirando e evite o ressalto', 'Mantenha-se em um alongamento leve em vez de puxar mais com impulso', 'Segure a posição com respiração constante e solte devagar; repita do outro lado se necessário']),
  ('dK9394r', 'Burpee', array['Comece em pé com os pés na largura dos ombros.', 'Antes de se mover, abaixe o corpo em uma posição de agachamento dobrando os joelhos e colocando as mãos no chão à sua frente.', 'Comece em um ritmo que permita que pés e braços se movam em sincronia.', 'Mova-se em um ritmo repetível, mantendo o movimento fluido e a respiração estável.', 'Mantenha o padrão repetível conforme a velocidade aumenta.', 'Mantenha o ritmo pelo intervalo planejado, desacelerando se a forma começar a falhar.']),
  ('DKBwJrL', 'Remada sentada unilateral com elástico', array['Sente-se em um banco ou cadeira com os pés apoiados e as costas retas.', 'Segure o elástico com uma mão e estenda o braço totalmente à sua frente.', 'Posicione o tronco e permita que os braços alcancem a frente sem curvar excessivamente.', 'Puxe os cotovelos para trás e traga a alça ou peso em direção ao tronco.', 'Mantenha ambos os ombros nivelados e resista a girar em direção ao braço que trabalha.', 'Estenda os braços para frente novamente sem deixar o tronco balançar; alterne os lados quando o exercício exigir.']),
  ('dmgMp3n', 'Remada inclinada com barra', array['Ajuste o banco para aproximadamente 45 graus.', 'Posicione-se de bruços no banco com o peito contra o apoio e os pés firmes.', 'Posicione o tronco e permita que os braços alcancem a frente sem curvar excessivamente.', 'Puxe os cotovelos para trás e traga a alça ou peso em direção ao tronco.', 'Traga os cotovelos para trás sem tracionar o tronco.', 'Estenda os braços para frente novamente sem deixar o tronco balançar.']),
  ('dNFYIU1', 'Desenvolvimento na máquina', array['Ajuste a altura do assento e do encosto da máquina em uma posição confortável.', 'Sente-se na máquina com as costas apoiadas no encosto e os pés firmes.', 'Contraia o tronco e alinhe os punhos com os antebraços.', 'Empurre o peso ou as alças para longe, mantendo o tronco contraído.', 'Mantenha os punhos alinhados e use um caminho de ombro que pareça natural.', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente.']),
  ('DoEYq4s', 'Agachamento sissy', array['Fique em pé com os pés na largura dos ombros e as pontas dos pés apontadas levemente para fora.', 'Use um objeto estável para se equilibrar, se necessário.', 'Contraia o abdômen e distribua a pressão por todo o pé.', 'Dobre os quadris e os joelhos para descer, mantendo os pés apoiados e os joelhos alinhados com os dedos dos pés.', 'Suba com o peito e os quadris subindo juntos; evite que os joelhos desabem para dentro.', 'Fique totalmente em pé, ajuste sua base e respiração, depois comece a próxima descida.']),
  ('DOoWcnA', 'Supino na máquina', array['Ajuste o assento ao seu corpo e acomode-se na máquina.', 'Segure as alças com as palmas voltadas para baixo e posicione os cotovelos em um ângulo de 90 graus.', 'Contraia o tronco e alinhe os punhos com os antebraços.', 'Empurre o peso ou as alças para longe, mantendo o tronco contraído.', 'Mantenha os punhos alinhados e use um caminho de ombro que pareça natural.', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente.']),
  ('DotAgEF', 'Supino declinado com pegada invertida', array['Prenda os pés em um banco declinado, mantendo a cabeça abaixo dos quadris.', 'Segure a barra com uma pegada invertida, logo além da largura dos ombros.', 'Contraia o tronco e alinhe os punhos com os antebraços.', 'Empurre o peso ou as alças para longe, mantendo o tronco contraído.', 'Mantenha as palmas na pegada escolhida sem dobrar os punhos para trás.', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente.']),
  ('dPmaUaU', 'Elevação de panturrilha em pé com halteres', array['Fique em pé com os pés na largura dos ombros, segurando um halter em cada mão.', 'Antes de se mover, tire os calcanhares do chão o mais alto possível, usando as panturrilhas.', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece firme.', 'Suba na ponta dos pés, levantando os calcanhares o mais alto que puder sem balançar.', 'Faça uma pausa no topo sem girar os tornozelos para fora.', 'Abaixe os calcanhares em um ritmo controlado antes de subir novamente.']),
  ('DptumMx', 'Puxada fechada com elástico', array['Conecte o elástico a um ponto de fixação alto, como uma barra fixa ou viga firme', 'Fique de frente para o ponto de fixação e segure o elástico com as palmas para cima, mãos na largura dos ombros', 'Sente-se erguido e ajuste os ombros antes de puxar a alça para baixo', 'Puxe a alça para baixo direcionando os cotovelos em direção às costelas; mantenha o tronco firme', 'Controle o elástico na volta em vez de deixar que ele puxe você rapidamente', 'Deixe a alça subir de forma controlada até que os braços estejam esticados, depois ajuste os ombros']),
  ('DpWMFP5', 'Rosca concentrada no cabo sentado', array['Sente-se em um banco de frente para a máquina de cabo com os pés apoiados', 'Segure o acessório do cabo com as palmas para cima e as mãos na largura dos ombros', 'Ajuste os ombros e os braços antes de flexionar os cotovelos', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco parado e deixe a flexão do cotovelo levantar o peso', 'Abaixe até que os cotovelos estejam quase retos, mantendo os braços parados']),
  ('DQ0cqkT', 'Mergulho em três bancos', array['Sente-se em um banco com as mãos segurando a borda, dedos apontando para a frente', 'Afaste o quadril do banco, apoiando seu peso com as mãos', 'Abaixe os ombros e mantenha os cotovelos apontados principalmente para trás', 'Flexione os cotovelos para descer entre os apoios; pare em uma profundidade confortável para os ombros', 'Escolha uma profundidade que permita manter os ombros confortáveis', 'Empurre com as mãos para subir, depois ajuste os ombros antes de outra repetição']),
  ('drfGhTV', 'Crucifixo inclinado no cabo', array['Ajuste a máquina de cabo em uma posição baixa e prenda as alças', 'Sente-se em um banco inclinado com as costas apoiadas no estofado e os pés firmes', 'Mantenha uma leve flexão nos cotovelos e ajuste os ombros antes de mover os braços', 'Com uma leve flexão nos cotovelos, aproxime os braços em um arco largo', 'Mantenha o ângulo do cotovelo quase inalterado durante o arco', 'Abra os braços de volta pelo mesmo arco sem deixar cair a carga']),
  ('dRTfGZT', 'Elevação lateral na máquina', array['Ajuste o assento ao seu corpo e acomode-se na máquina', 'Segure as alças com as palmas voltadas para baixo e mantenha os braços retos', 'Comece com uma carga gerenciável e uma pequena flexão nos cotovelos', 'Eleve os braços para os lados até a altura dos ombros, sem inclinar ou encolher os ombros', 'Pare perto da altura dos ombros em vez de encolher os ombros para levantar mais alto', 'Abaixe os braços lentamente para as laterais sem balançar o peso']),
  ('Dsfz0Id', 'Rosca concentrada com barra EZ sentado', array['Apoie ambos os pés no chão sentado em um banco; segure uma barra EZ com as palmas para cima', 'Apoie o cotovelo na parte interna da coxa, logo acima do joelho', 'Ajuste os ombros e os braços antes de flexionar os cotovelos', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco parado e deixe a flexão do cotovelo levantar o peso', 'Abaixe até que os cotovelos estejam quase retos, mantendo os braços parados']),
  ('DsgkuIt', 'Elevação lateral com halteres', array['Fique em pé com os pés na largura dos ombros e segure um halter em cada mão, palmas voltadas para o corpo', 'Mantenha a coluna em uma posição neutra e confortável e contraia o abdômen', 'Comece com uma carga gerenciável e uma pequena flexão nos cotovelos', 'Eleve os braços para os lados até a altura dos ombros, sem inclinar ou encolher os ombros', 'Pare perto da altura dos ombros em vez de encolher os ombros para levantar mais alto', 'Abaixe os braços lentamente para as laterais sem balançar o peso']),
  ('DT14T9T', 'Puxada com braços retos no cabo (com corda)', array['Conecte uma corda à máquina de cabo na regulagem mais alta', 'Fique de frente para a máquina em uma base estável com os pés na largura dos ombros', 'Sente-se erguido e ajuste os ombros antes de puxar a alça para baixo', 'Puxe a alça para baixo direcionando os cotovelos em direção às costelas; mantenha o tronco firme', 'Puxe com os cotovelos em vez de se inclinar muito para trás para mover a alça', 'Deixe a alça subir de forma controlada até que os braços estejam esticados, depois ajuste os ombros']),
  ('dTg95eZ', 'Abdominal com toque no joelho', array['Deite-se de costas com os joelhos flexionados e os pés apoiados', 'Coloque as mãos atrás da cabeça com os cotovelos apontados para fora', 'Posicione a pelve e mantenha o pescoço relaxado antes de subir', 'Flexione a caixa torácica em direção à pelve, deixando o abdômen mover o tronco', 'Deixe um pequeno espaço entre o queixo e o peito; mantenha o movimento no tronco', 'Abaixe os ombros ou o tronco com controle antes da próxima flexão']),
  ('DU5Kkj2', 'Rosca inversa unilateral em pé com halteres', array['Fique em pé com os pés na largura dos ombros e segure um halter em uma mão com as palmas para baixo', 'Mantenha o braço esticado e próximo ao corpo, com a palma virada para baixo', 'Posicione os ombros e os braços antes de flexionar os cotovelos', 'Flexione o peso com as palmas viradas para baixo, mantendo os cotovelos próximos e o tronco imóvel', 'Mantenha ambos os ombros nivelados e evite virar em direção ao braço em trabalho', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços imóvel; alterne os lados quando necessário']),
  ('dU605di', 'Tríceps com corda na polia', array['Conecte um acessório de corda a uma polia alta em uma máquina de cabo', 'Fique de frente para a máquina com os pés na largura dos ombros e uma leve flexão nos joelhos', 'Fique a uma distância suficiente da pilha para que o cabo fique tenso', 'Mantenha os cotovelos próximos às costelas e estique os braços contra o cabo', 'Mantenha os cotovelos próximos ao corpo em vez de deixar os ombros balançarem', 'Retorne suavemente ao início antes de repetir']),
  ('DU7I633', 'Supino inclinado com pegada inversa com barra', array['Ajuste o banco para aproximadamente 45 graus', 'Sente-se no banco com os pés apoiados', 'Estabilize o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou os puxadores para longe enquanto mantém o tronco firme', 'Mantenha as palmas das mãos na pegada escolhida sem dobrar os punhos para trás', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente']),
  ('dVeWXf2', 'Barra fixa supinada', array['Suspenda-se em uma barra fixa com as palmas voltadas para você e as mãos na largura dos ombros', 'Estabilize o tronco e puxe o corpo em direção à barra, liderando com o peito', 'Comece de uma suspensão controlada com os ombros ativos em vez de relaxados', 'Puxe os cotovelos para baixo e traga a parte superior do peito em direção à barra sem chutar as pernas', 'Evite balançar as pernas para ultrapassar a barra', 'Abaixe até esticar os braços sem cair repentinamente do topo']),
  ('DwhEmmE', 'Supino declinado com halteres', array['Posicione-se em um banco declinado com os pés presos e a cabeça mais baixa que os quadris', 'Pegue um halter em cada mão e estenda os braços para cima acima do peito, com as palmas para a frente', 'Estabilize o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou os puxadores para longe enquanto mantém o tronco firme', 'Mantenha os punhos alinhados e use um caminho de ombro que pareça natural', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente']),
  ('Dx2RIva', 'Elevação de panturrilha unilateral no leg press', array['Ajuste o assento da máquina de leg press para que seus joelhos fiquem levemente flexionados quando seus pés estiverem no trenó', 'Sente-se na máquina com as costas apoiadas no encosto e os pés no trenó, na largura dos ombros', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece imóvel', 'Suba na ponta dos pés, levantando os calcanhares o mais alto possível sem balançar', 'Mantenha a pelve nivelada enquanto a perna de apoio faz o trabalho', 'Abaixe os calcanhares em um ritmo moderado antes de subir novamente; alterne os lados quando necessário']),
  ('dXz8zjF', 'Rosca drag na polia', array['Fique de frente para a máquina de cabo com uma postura estável e os pés na largura dos ombros', 'Segure o acessório do cabo com as palmas voltadas para cima e os braços esticados', 'Posicione os ombros e os braços antes de flexionar os cotovelos', 'Dobre os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco imóvel e deixe a flexão do cotovelo levantar o peso', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços imóvel']),
  ('dZl9Q27', 'Extensão de tríceps com barra em pé', array['Fique em pé com os pés na largura dos ombros e segure uma barra com as palmas voltadas para baixo', 'Eleve a barra acima da cabeça e estique os braços', 'Posicione os braços antes de estender os cotovelos', 'Mantenha os braços apontados para cima e estenda os cotovelos sem abrir as costelas', 'Mantenha os braços firmes enquanto os antebraços se movimentam', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição']),
  ('dzz6BiV', 'Agachamento sumô no Smith', array['Prepare a máquina Smith com a barra na altura do quadril', 'Fique em pé com os pés mais afastados que a largura dos ombros e os dedos voltados para fora', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione o quadril e os joelhos para descer, mantendo os pés apoiados e os joelhos alinhados com os dedos', 'Empurre para cima com o peito e o quadril subindo juntos, evitando que os joelhos caiam para dentro', 'Fique totalmente em pé, ajuste a base e a respiração, então inicie a próxima descida']),
  ('e1e76I2', 'Pular corda', array['Segure os manípulos da corda com as palmas voltadas para dentro', 'Fique em pé com os pés na largura dos ombros e joelhos flexionados', 'Flexione levemente o quadril e os joelhos para preparar o salto', 'Carregue as pernas com uma pequena flexão, depois impulsione pelo chão e aterrisse suavemente', 'Aterrisse com quadril e joelhos flexionados, deixando os pés absorverem o impacto', 'Absorva a aterrissagem pelo quadril e joelhos antes de repetir']),
  ('e25F58f', 'Crucifixo inverso com um braço com halter (com apoio)', array['Apoie ambos os pés sentado em um banco com as costas retas', 'Pegue um halter em uma das mãos com a palma voltada para dentro', 'Mantenha uma leve flexão no cotovelo e posicione os ombros antes de mover os braços', 'Abra os braços para fora e para trás com uma leve flexão no cotovelo, unindo as escápulas', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço em movimento', 'Abra os braços de volta pelo mesmo arco sem deixar cair a carga e alterne os lados quando necessário']),
  ('e4aFmFY', 'Elevação frontal com peso', array['Fique em pé com os pés na largura dos ombros, segurando um halter em cada mão com as palmas voltadas para as coxas', 'Com os braços retos, expire e eleve os halteres à sua frente até a altura dos ombros', 'Comece com uma carga gerenciável e uma pequena flexão nos cotovelos', 'Eleve os braços para a frente até a altura dos ombros, mantendo as costelas para baixo e o tronco parado', 'Pare perto da altura dos ombros em vez de encolher os ombros para subir mais', 'Abaixe os braços lentamente para as laterais sem balançar o peso']),
  ('e4ojVhP', 'Rosca bicep com pegada inversa com halter', array['Fique erguido com um halter em cada mão, palmas voltadas para baixo e braços retos', 'Com os braços parados, expire e flexione os pesos enquanto contrai os bíceps', 'Posicione os ombros e braços antes de flexionar os cotovelos', 'Flexione o peso com as palmas voltadas para baixo, mantendo os cotovelos próximos e o tronco parado', 'Mantenha as palmas na pegada escolhida sem curvar os punhos para trás', 'Abaixe até que os cotovelos estejam quase retos, mantendo os braços parados']),
  ('E4PwJqI', 'Flexão de pernas inversa autoassistida', array['Posicione-se de bruços em uma máquina de flexão de pernas com as pernas estendidas e os tornozelos encaixados sob a alavanca estofada', 'Coloque as mãos nos puxadores laterais da máquina para apoio', 'Alinhe os joelhos com a borda da máquina ou do banco antes de iniciar a flexão', 'Flexione os joelhos para puxar o apoio em sua direção sem levantar o quadril do suporte', 'Mantenha o quadril parado enquanto os joelhos flexionam', 'Retorne suavemente ao início antes de repetir']),
  ('E4R8Hz1', 'Elevação de quadril com elástico', array['Deite-se de costas com os joelhos flexionados e os pés apoiados', 'Coloque uma faixa de resistência logo acima dos joelhos', 'Apoie os pés e impeça que as costelas se abram enquanto o quadril se prepara para subir', 'Pressione pelos pés e eleve o quadril até que o tronco e as coxas fiquem alinhados', 'Controle a faixa na volta em vez de deixar que ela puxe você de volta', 'Abaixe o quadril de forma constante e mantenha os pés apoiados para a próxima elevação']),
  ('ealLwvX', 'Elevação de joelhos alta contra a parede', array['Fique de frente para uma parede com os pés na largura dos quadris', 'Apoie as mãos na parede para dar suporte', 'Comece em um ritmo que permita que pés e braços se movam em sincronia', 'Mova-se em um ritmo repetível, mantendo o movimento fluido e a respiração constante', 'Mantenha o padrão repetível conforme a velocidade aumenta', 'Mantenha o ritmo pelo intervalo planejado, diminuindo a velocidade se a forma começar a falhar']),
