  ('eZyBC3j', 'Remada curvada com barra', array['Fique em pé com os pés na largura dos ombros e joelhos flexionados', 'Incline o tronco para a frente a partir do quadril, mantendo a coluna firme e o peito estufado', 'Posicione o tronco e deixe os braços estendidos para a frente sem curvar excessivamente', 'Puxe os cotovelos para trás e leve a barra ou peso em direção ao tronco', 'Traga os cotovelos para trás sem dar trancos no tronco', 'Estenda os braços para a frente novamente sem deixar o tronco balançar']),
  ('f1jf47L', 'Desenvolvimento sentado com halteres (pegada neutra)', array['Sente-se em um banco com um halter em cada mão, palmas viradas para dentro', 'Antes de mover, eleve os halteres até a altura dos ombros, com os cotovelos flexionados e palmas viradas para a frente', 'Contraia o abdômen e alinhe os punhos com os antebraços', 'Empurre o peso ou pegas para cima mantendo o tronco firme', 'Mantenha os punhos alinhados e use um trajeto natural para os ombros', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente']),
  ('F1KxjBa', 'Rosca martelo no banco scott com halter', array['Fique em pé com um halter em cada mão, palmas viradas para o tronco', 'Mantenha os cotovelos próximos ao tronco e aponte as palmas das mãos para a frente', 'Apoie a parte superior do braço no suporte do banco scott, deixando o cotovelo livre para flexionar', 'Flexione o peso mantendo a parte superior dos braços em contato com o suporte', 'Mantenha as palmas viradas uma para a outra e os punhos retos', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços imóvel']),
  ('f38OEuO', 'Alongamento de dorsal ajoelhado', array['Ajoelhe-se no chão com os joelhos na largura do quadril e os dedos dos pés apontando para trás', 'Eleve os braços acima da cabeça e entrelace os dedos', 'Estabilize-se na posição inicial e respire calmamente antes de aprofundar o movimento', 'Aproxime-se do alongamento até sentir uma tensão leve; continue respirando e evite balançar', 'Mantenha um alongamento leve em vez de puxar mais com impulso', 'Mantenha a posição com respiração constante, depois solte suavemente; repita do outro lado, se necessário']),
  ('F3xgbjF', 'Rosca bicep inclinada com halteres', array['Sente-se em um banco inclinado com um halter em cada mão, palmas viradas para a frente e braços retos', 'Com a parte superior dos braços estática, expire e flexione os pesos contraindo os bíceps', 'Posicione os ombros e a parte superior dos braços antes de flexionar os cotovelos', 'Flexione os cotovelos para levar o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco imóvel e use a flexão do cotovelo para levantar o peso', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços imóvel']),
  ('f4xtKBj', 'Puxada alta assistida em pé', array['Ajuste a máquina para o peso e altura desejados', 'Fique de frente para a máquina em uma postura estável com os pés na largura dos ombros', 'Inicie a partir de uma suspensão controlada, com os ombros ativos e não relaxados', 'Puxe os cotovelos para baixo e aproxime a parte superior do peito da barra sem chutar as pernas', 'Evite balançar as pernas para passar da barra', 'Desça com os braços esticados sem despencar do topo']),
  ('F56Xpw3', 'Paralelas com peso corporal', array['Posicione-se entre as barras paralelas com os braços retos e o corpo esticado', 'Antes de mover, abaixe o corpo flexionando os cotovelos até que a parte superior dos braços fique paralela ao chão', 'Abaixe os ombros e mantenha os cotovelos apontados principalmente para trás', 'Flexione os cotovelos para descer entre os suportes; pare em uma profundidade confortável para os ombros', 'Escolha uma profundidade que mantenha os ombros confortáveis', 'Empurre com as mãos para subir, depois ajuste os ombros antes da próxima repetição']),
  ('f7fnAIB', 'Remada no agachamento com cabo (com acessório de corda)', array['Conecte uma corda a uma polia na altura da cintura', 'Fique de frente para a polia em uma postura estável com os pés na largura dos ombros', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione o quadril e os joelhos para abaixar, mantendo os pés firmes e os joelhos alinhados com os dedos dos pés', 'Empurre para cima subindo o peito e o quadril juntos; evite que os joelhosancorem para dentro', 'Fique totalmente em pé, ajuste sua postura e respiração, depois inicie a próxima descida']),
  ('F7vjXqT', 'Flexão inclinada (na caixa)', array['Apoie as mãos na borda de uma caixa ou superfície elevada, um pouco além da largura dos ombros.', 'Estique as pernas para trás, apoiando-se na ponta dos pés, criando uma linha reta da cabeça aos calcanhares.', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos.', 'Flexione os cotovelos para abaixar o peito, mantendo o corpo alinhado.', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos flexionam.', 'Empurre de volta até esticar os braços, mantendo o alinhamento corporal.']),
  ('f7Y9eDZ', 'Thruster com barra', array['Fique em pé com os pés na largura dos ombros, segurando uma barra na altura dos ombros com as palmas voltadas para baixo.', 'Antes de se mover, agache-se flexionando os joelhos e empurrando os quadris para trás.', 'Apoie o peso com firmeza e contraia o abdômen antes de descer para o agachamento.', 'Levante-se do agachamento e use a impulsão das pernas para erguer o peso acima da cabeça.', 'Deixe a força das pernas iniciar o movimento sem estufar as costelas.', 'Retorne pelo mesmo caminho em um ritmo controlado.']),
  ('f91FwXG', 'Encolhimento de ombros na máquina sem pegada', array['Ajuste o assento ao seu corpo e acomode-se na máquina.', 'Segure as alças com as palmas voltadas para dentro e os braços esticados.', 'Deixe os braços soltos ao longo do corpo e mantenha a cabeça neutra.', 'Eleve os ombros em direção às orelhas sem flexionar os cotovelos ou girar os ombros.', 'Suba e desça na vertical sem fazer círculos com os ombros.', 'Retorne suavemente à posição inicial antes de repetir.']),
  ('f9lVSSI', 'Saltos com afastamento', array['Fique em pé com os pés na largura dos ombros.', 'Antes de se mover, flexione os joelhos e abaixe o corpo em posição de agachamento.', 'Flexione levemente os quadris e joelhos para preparar o salto.', 'Carregue as pernas com uma pequena flexão, impulsione-se no chão e aterrisse suavemente.', 'Aterrisse com os quadris e joelhos flexionados, deixando os pés absorverem o impacto.', 'Absorva a aterrissagem pelos quadris e joelhos antes de repetir.']),
  ('faHKVkK', 'Rosca bíceps com barra em pé e pegada aberta', array['Fique em pé com os pés na largura dos ombros e segure uma barra com as palmas voltadas para cima, com as mãos mais afastadas que a largura dos ombros.', 'Mantenha a coluna em uma posição neutra e confortável e os cotovelos próximos ao tronco.', 'Posicione os ombros e a parte superior dos braços antes de flexionar os cotovelos.', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco.', 'Mantenha o tronco firme e deixe a flexão do cotovelo erguer o peso.', 'Abaixe até que os cotovelos estejam quase esticados, mantendo a parte superior dos braços imóvel.']),
  ('FAoIFMw', 'Mergulho unilateral', array['Fique de costas para um banco ou cadeira, em uma base estável com os pés na largura dos ombros.', 'Apoie uma mão no banco ou cadeira atrás de você, com os dedos apontados para o corpo.', 'Posicione os ombros para baixo e mantenha os cotovelos apontados majoritariamente para trás.', 'Flexione os cotovelos para abaixar o corpo entre os apoios; pare em uma profundidade confortável para os ombros.', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço em movimento.', 'Empurre com as mãos para subir, ajuste os ombros antes de outra repetição e alterne os lados quando necessário.']),
  ('fBnPpzd', 'Flexão de pernas deitado assistida', array['Posicione-se de bruços em um colchonete ou banco com as pernas esticadas.', 'Peça ajuda a um parceiro ou use um elástico de resistência para prender os tornozelos.', 'Alinhe os joelhos com a borda da máquina ou do banco antes de iniciar a flexão.', 'Flexione os joelhos para puxar o apoio em sua direção sem levantar os quadris da base.', 'Mantenha os quadris imóveis enquanto os joelhos flexionam.', 'Retorne suavemente à posição inicial antes de repetir.']),
  ('Ff18ItA', 'Mergulho com peso na barra reta', array['Posicione-se entre as barras paralelas com os braços esticados e o corpo reto.', 'Antes de se mover, abaixe o corpo flexionando os cotovelos até que a parte superior dos braços fique paralela ao solo.', 'Posicione os ombros para baixo e mantenha os cotovelos apontados majoritariamente para trás.', 'Flexione os cotovelos para abaixar o corpo entre os apoios; pare em uma profundidade confortável para os ombros.', 'Escolha uma profundidade que permita manter os ombros confortáveis.', 'Empurre com as mãos para subir e ajuste os ombros antes de outra repetição.']),
  ('fF6GKVh', 'Alongamento de perna sentado na cadeira', array['Sente-se na borda de uma cadeira com as costas retas e os pés apoiados', 'Estique uma perna para a frente mantendo o calcanhar no chão', 'Ajuste-se na posição inicial e respire calmamente antes de aprofundar', 'Aproxime-se do alongamento até sentir uma leve tensão, continue respirando e evite balançar', 'Mantenha um alongamento leve em vez de puxar mais com impulso', 'Segure a posição com respiração constante e solte devagar, repita do outro lado se necessário']),
  ('ffQsyBj', 'Rosca em pé com halteres unilateral', array['Fique em pé com um halter em uma mão, palma virada para a frente e braço esticado', 'Com o braço imóvel, expire e suba o peso contraindo os bíceps', 'Posicione os ombros e braços antes de dobrar os cotovelos', 'Dobre os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha ambos os ombros nivelados e evite girar para o lado do braço em movimento', 'Abaixe até que os cotovelos estejam quase retos, mantendo os braços parados, troque de lado ao terminar a série']),
  ('FFRP97T', 'Abdominal borboleta', array['Deite-se de costas com os joelhos dobrados e os pés apoiados', 'Coloque as mãos atrás da cabeça com os cotovelos apontados para fora', 'Ajuste a pelve e mantenha o pescoço relaxado antes de subir', 'Junte as solas dos pés, deixe os joelhos abertos e aproxime as costelas da pelve', 'Deixe um pequeno espaço entre o queixo e o peito, mantendo o movimento no tronco', 'Abaixe os ombros ou o tronco com controle antes da próxima repetição']),
  ('fgc9Xdl', 'Elevação de panturrilha em pé no cabo unilateral', array['Fique de frente para a máquina de cabo com uma base estável e pés na largura dos ombros', 'Use a máquina de cabo para apoio', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo fica firme', 'Suba na ponta dos pés, elevando os calcanhares o mais alto possível sem balançar', 'Mantenha a pelve nivelada enquanto a perna de apoio faz o esforço', 'Abaixe os calcanhares em ritmo controlado antes de subir novamente, troque de lado ao terminar a série']),
  ('Fhdtwf3', 'Remada curvada unilateral na máquina', array['Fique em pé com os pés na largura dos ombros, joelhos levemente flexionados e segure uma barra com as palmas para baixo', 'Incline-se para a frente a partir dos quadris, com a coluna firme e a cabeça erguida', 'Ajuste o tronco e permita que os braços fiquem estendidos para a frente sem curvar excessivamente', 'Puxe os cotovelos para trás e traga a carga ou peso em direção ao tronco', 'Mantenha ambos os ombros nivelados e evite girar para o lado do braço em movimento', 'Estique os braços para a frente novamente sem deixar o tronco balançar, troque de lado ao terminar a série']),
  ('fhZQPlV', 'Giro no cabo (cima-baixo)', array['Fique em pé com os pés na largura dos ombros, de frente para a máquina de cabo', 'Segure a alça do cabo com as duas mãos na altura do peito, mantendo os braços relaxados', 'Ajuste a pelve e faça o giro a partir da caixa torácica', 'Gire o tronco enquanto os quadris e a parte inferior do corpo permanecem o mais estáveis possível', 'Mantenha o giro suave em vez de lançar os braços pelo corpo', 'Retorne pelo centro antes de girar para o outro lado']),
  ('fI18Rbc', 'Remada alta com barra', array['Fique em pé com os pés na largura dos ombros e segure uma barra com as palmas para baixo, com as mãos um pouco além da largura dos ombros', 'Mantenha a barra pendurada à frente das coxas com os braços esticados', 'Ajuste o tronco e permita que os braços fiquem estendidos para a frente sem curvar excessivamente', 'Puxe os cotovelos para trás e traga a carga ou peso em direção ao tronco', 'Puxe os cotovelos para trás sem dar trancos no tronco', 'Estique os braços para a frente novamente sem deixar o tronco balançar']),
  ('fjjY3N4', 'Flexão de perna invertida (na máquina de cabo)', array['Ajuste a máquina de cabo para que as tiras de tornozelo fiquem na posição mais baixa', 'Posicione-se de bruços no banco com as pernas estendidas e as tiras de tornozelo presas aos pés', 'Alinhe os joelhos com a borda da máquina ou do banco antes de iniciar o movimento', 'Dobre os joelhos para puxar o apoio em direção a você sem levantar os quadris do suporte', 'Mantenha os quadris parados enquanto os joelhos dobram', 'Retorne devagar à posição inicial antes de repetir']),
  ('FkBIE6a', 'Flexão de pernas com halter deitado', array['Deite-se de bruços em um banco plano com os joelhos logo além da borda', 'Segure um halter leve firmemente entre os pés e mantenha o quadril no banco', 'Contraia o tronco e mantenha as coxas apoiadas no banco', 'Flexione os joelhos para puxar os calcanhares em direção aos glúteos sem levantar o quadril', 'Abaixe o peso lentamente até que as pernas estejam quase retas, depois ajuste a pegada antes de repetir']),
  ('fKZgDEO', 'Elevação de panturrilha unilateral (sobre um halter)', array['Fique em pé com os pés na largura dos quadris e segure um halter em uma das mãos', 'Antes de se mover, tire um pé do chão e equilibre-se sobre o outro pé', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece estável', 'Eleve-se na ponta dos pés, levantando os calcanhares o mais alto possível sem balançar', 'Faça uma pausa no topo sem girar os tornozelos para fora', 'Abaixe os calcanhares em um ritmo controlado antes de subir novamente']),
  ('fNGumX0', 'Passo para frente e para trás', array['Fique em pé com os pés na largura dos ombros', 'Avance com o pé direito, flexionando o joelho e abaixando o corpo em posição de afundo', 'Comece em um ritmo que permita que os pés e os braços se movam em sincronia', 'Mova-se em um ritmo repetível, mantendo o movimento suave e a respiração constante', 'Mantenha o padrão repetível conforme a velocidade aumenta', 'Mantenha o ritmo pelo intervalo planejado, diminuindo a velocidade se a forma começar a falhar']),
  ('fprd84i', 'Desenvolvimento anti-gravidade com barra EZ', array['Comece em pé com os pés na largura dos ombros e segurando a barra EZ com as palmas para baixo', 'Eleve a barra até a altura dos ombros, mantendo os cotovelos levemente flexionados e as palmas viradas para a frente', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou os puxadores para longe enquanto mantém o tronco contraído', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural', 'Abaixe o peso até a altura inicial sob controle antes de empurrar novamente']),
  ('FQXdXzY', 'Extensão de tríceps sentado com halteres', array['Sente-se em um banco com as costas retas e os pés apoiados no chão', 'Pegue um halter com as duas mãos com as palmas para baixo e eleve-o acima da cabeça', 'Posicione os braços firmemente antes de estender os cotovelos', 'Mantenha os braços firmes e estenda através dos cotovelos para mover o peso', 'Mantenha os braços firmes enquanto os antebraços se movimentam', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição']),
  ('FS63wTN', 'Desenvolvimento com impulso com halteres', array['Fique em pé com os pés na largura dos ombros, segurando um halter em cada mão na altura dos ombros', 'Antes de se mover, flexione levemente os joelhos e faça um agachamento curto, depois estenda as pernas explosivamente e empurre os halteres para cima', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou os puxadores para longe enquanto mantém o tronco contraído', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural', 'Abaixe o peso até a altura inicial sob controle antes de empurrar novamente']),
  ('FSD6PGL', 'Pullover com halter na bola suíça', array['Sente-se em uma bola suíça e segure um halter com as duas mãos acima do peito, com os braços estendidos', 'Com controle, abaixe o halter atrás da cabeça mantendo os braços retos', 'Abaixe as costelas e mantenha uma leve flexão nos cotovelos antes de abaixar o peso', 'Abaixe o peso em arco atrás da cabeça até sentir um estiramento confortável nos ombros', 'Mantenha a bola estável e use os pés para controlar o equilíbrio', 'Puxe o peso de volta sobre o peito ao longo do mesmo arco, sem levantar as costelas']),
  ('FSF9WOs', 'Mergulho em barras paralelas com pegada aberta para peito', array['Posicione-se nas barras paralelas com os braços retos e o corpo suspenso no ar', 'Incline-se ligeiramente para a frente e abaixe o corpo flexionando os cotovelos até que o peito fique logo acima das barras', 'Abaixe os ombros e mantenha os cotovelos apontados principalmente para trás', 'Flexione os cotovelos para abaixar entre os suportes; pare em uma profundidade confortável para os ombros', 'Escolha uma profundidade que permita que os ombros fiquem confortáveis', 'Empurre com as mãos para subir, depois ajuste os ombros antes de outra repetição']),
  ('fSrPP6B', 'Extensão de tríceps na polia', array['Fique em pé com os pés na largura dos ombros e joelhos levemente flexionados.', 'Estique os braços à sua frente, paralelos ao solo.', 'Contraia o abdômen e alinhe os punhos com os antebraços.', 'Empurre o peso ou os puxadores mantendo o tronco firme.', 'Mantenha os punhos alinhados e use uma trajetória de ombro natural.', 'Desça o peso até a altura inicial de forma controlada antes de empurrar novamente.']),
  ('fTlkJop', 'Elevação lateral deitado com halteres', array['Deite-se de lado com as pernas estendidas e a cabeça apoiada no braço.', 'Segure um halter com a mão de cima e a palma voltada para baixo.', 'Comece com uma carga adequada e uma leve flexão nos cotovelos.', 'Levante os pesos para longe do torso até a altura dos ombros, mantendo os cotovelos levemente flexionados.', 'Pare perto da altura dos ombros em vez de encolher os ombros para subir mais.', 'Desça os braços lentamente para as laterais sem balançar o peso.']),
  ('fUBheHs', 'Remada sentada no cabo', array['Sente-se na máquina de remada com os pés apoiados e os joelhos levemente flexionados.', 'Segure os puxadores com as palmas voltadas para baixo, com a coluna firme e os ombros relaxados.', 'Posicione o tronco e deixe os braços esticarem para a frente sem curvar excessivamente.', 'Puxe os cotovelos para trás e traga o puxador ou peso em direção ao torso.', 'Traga os cotovelos para trás sem dar trancos no torso.', 'Estique os braços para a frente novamente sem deixar o tronco balançar.']),
  ('FVM1AUZ', 'Remada curvada na máquina com pegada supinada', array['Ajuste o assento ao seu corpo e posicione-se na máquina.', 'Segure os puxadores com as palmas voltadas para baixo, um pouco além da largura dos ombros.', 'Posicione o tronco e deixe os braços esticarem para a frente sem curvar excessivamente.', 'Puxe os cotovelos para trás e traga o puxador ou peso em direção ao torso.', 'Mantenha as palmas na pegada escolhida sem dobrar os punhos para trás.', 'Estique os braços para a frente novamente sem deixar o tronco balançar.']),
  ('FVmZVhk', 'Crucifixo invertido baixo no cabo', array['Conecte os puxadores às polias baixas de uma máquina de cabo e selecione um peso adequado.', 'Posicione-se no meio da máquina com os pés na largura dos ombros e uma leve flexão nos joelhos.', 'Mantenha uma leve flexão nos cotovelos e ajuste os ombros antes de mover os braços.', 'Com uma leve flexão nos cotovelos, aproxime os braços em um arco amplo.', 'Mantenha o ângulo do cotovelo quase inalterado durante o arco.', 'Abra os braços de volta pelo mesmo arco sem deixar cair a carga.']),
  ('FWdVhcW', 'Rotação externa de ombro em pé no cabo', array['Fique em pé com os pés na largura dos ombros e joelhos levemente flexionados.', 'Segure o puxador do cabo com o braço estendido à sua frente, paralelo ao solo.', 'Posicione a pelve e faça a rotação através da caixa torácica.', 'Gire através do torso enquanto os quadris e a parte inferior do corpo permanecem o mais firmes possível.', 'Mantenha a rotação suave em vez de lançar os braços pelo corpo.', 'Retorne ao centro antes de girar para o outro lado.']),
  ('fXfqg1E', 'Pull-up com peso e uma mão', array['Segure a barra de pull-up com as palmas voltadas para baixo, um pouco além da largura dos ombros.', 'Fique suspenso na barra com o braço esticado e o corpo reto.', 'Comece de uma suspensão controlada com os ombros ativos em vez de relaxados.', 'Puxe os cotovelos para baixo e traga a parte superior do peito em direção à barra sem chutar as pernas.', 'Evite balançar as pernas para passar da barra.', 'Desça com os braços esticados sem cair repentinamente do topo.']),
  ('FxhcxUW', 'Elevação de panturrilha sentado com uma perna com halter - pegada neutra', array['Sente-se em um banco ou cadeira com os pés apoiados e um halter sobre as coxas.', 'Apoie um pé em uma superfície elevada, como um degrau ou bloco, com o calcanhar para fora da borda.', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece imóvel.', 'Suba na ponta dos pés, levantando os calcanhares o mais alto possível sem balançar.', 'Mantenha a pelve nivelada enquanto a perna de apoio faz o trabalho.', 'Desça os calcanhares em um ritmo controlado antes de subir novamente; alterne os lados quando necessário.']),
  ('FY3UdNT', 'Elevação de panturrilha na bola suíça na parede (bola de tênis entre os tornozelos)', array['Fique de frente para a parede em uma base estável com os pés na largura dos ombros.', 'Coloque uma bola suíça entre a parede e a sua lombar.', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece imóvel.', 'Suba na ponta dos pés, elevando os calcanhares o mais alto possível sem balançar.', 'Mantenha a bola firme e use os pés para controlar o seu equilíbrio.', 'Abaixe os calcanhares em um ritmo controlado antes de subir novamente.']),
  ('fY68AyX', 'Rosca martelo com halter na bola suíça', array['Sente-se em uma bola suíça com os pés apoiados no chão e as costas retas.', 'Segure um halter em cada mão com as palmas voltadas para o corpo e os braços esticados.', 'Posicione os ombros e a parte superior dos braços antes de flexionar os cotovelos.', 'Faça a rosca com as palmas voltadas uma para a outra e os cotovelos próximos aos lados; evite balançar para trás.', 'Mantenha a bola firme e use os pés para controlar o seu equilíbrio.', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços imóvel.']),
  ('fy7Tgy4', 'Rosca scott alternada com halter', array['Sente-se em um banco scott com um halter em cada mão, palmas voltadas para o tronco e braços esticados.', 'Deixe os cotovelos se moverem enquanto a parte superior dos braços permanece no lugar, expire e flexione os pesos enquanto contrai os bíceps.', 'Apoie a parte superior do braço em trabalho contra o suporte do banco scott e deixe o cotovelo livre para dobrar.', 'Flexione o peso enquanto a parte superior dos braços permanece em contato com o suporte.', 'Conclua o movimento de um lado antes que o outro lado comece.', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços imóvel; alterne os lados quando a série exigir.']),
  ('fZFZ704', 'Rotação russa com peso', array['Sente-se no chão com os joelhos flexionados e os pés apoiados.', 'Segure um peso ou medicine ball com ambas as mãos na altura do peito.', 'Estabilize a pelve e faça a rotação através da caixa torácica.', 'Gire o tronco enquanto o quadril e a parte inferior do corpo permanecem o mais firmes possível.', 'Mantenha a rotação suave em vez de lançar os braços pelo corpo.', 'Retorne ao centro antes de girar para o outro lado.']),
  ('G08RZcQ', 'Rosca com cabo', array['Fique de frente para a máquina de cabo em uma base estável com os pés na largura dos ombros.', 'Segure o acessório do cabo com as palmas voltadas para cima.', 'Posicione os ombros e a parte superior dos braços antes de flexionar os cotovelos.', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco.', 'Mantenha o tronco imóvel e deixe a flexão do cotovelo levantar o peso.', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços imóvel.']),
  ('G1qWW6M', 'Puxada com uma mão com peso', array['Segure a barra de puxada com as palmas voltadas para baixo, logo além da largura dos ombros.', 'Suspenda-se na barra com o braço esticado e o corpo reto.', 'Comece de uma suspensão controlada com os ombros ativos em vez de relaxados.', 'Puxe os cotovelos para baixo e traga a parte superior do peito em direção à barra sem chutar as pernas.', 'Evite balançar as pernas para ultrapassar a barra.', 'Abaixe até esticar os braços sem cair repentinamente do topo.']),
  ('g2oKspu', 'Abdominal curvado', array['Deite-se de costas com os joelhos flexionados e os pés apoiados.', 'Coloque as mãos atrás da cabeça com os cotovelos apontados para fora.', 'Estabilize a pelve e mantenha o pescoço relaxado antes de subir.', 'Flexione a caixa torácica em direção à pelve, permitindo que o abdômen mova o tronco.', 'Deixe um pequeno espaço entre o queixo e o peito; mantenha o movimento no tronco.', 'Abaixe os ombros ou o tronco com controle antes da próxima repetição.']),
  ('g376LuL', 'Pressão de panturrilha deitado no trenó', array['Ajuste a máquina de trenó para um peso confortável.', 'Sente-se na máquina de trenó com as costas apoiadas no encosto e os pés na plataforma.', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece imóvel.', 'Suba na ponta dos pés, elevando os calcanhares o mais alto possível sem balançar.', 'Faça uma pausa no topo sem girar os tornozelos para fora.', 'Abaixe os calcanhares em um ritmo controlado antes de subir novamente.']),
  ('G61cXLk', 'Remada alta ajoelhado com cabo (com corda)', array['Conecte um puxador de corda a uma polia baixa do cabo e ajoelhe-se de frente para a maquina', 'Segure a corda com uma pegada neutra (palmas das maos voltadas uma para a outra) e estenda completamente os bracos na sua frente', 'Posicione o tronco e permita que os bracos alcancem a frente sem curvar excessivamente', 'Puxe os cotovelos para tras e aproxime o puxador ou peso do seu tronco', 'Traga os cotovelos para tras sem dar impulso com o tronco', 'Estenda os bracos para a frente novamente sem deixar o tronco balancar']),
  ('G70mEAJ', 'Barra fixa (pegada paralela fechada)', array['Suspenda-se em uma barra fixa com uma pegada paralela fechada, palmas das maos voltadas para voce', 'Ative os musculos das costas e puxe seu corpo em direcao a barra, mantendo os cotovelos proximos ao corpo', 'Comece a partir de uma suspensao controlada com os ombros ativos em vez de relaxados', 'Puxe os cotovelos para baixo e aproxime a parte superior do peito da barra sem chutar as pernas', 'Evite balancar as pernas para passar da barra', 'Desca ate os bracos ficarem estendidos sem cair repentinamente do topo']),
  ('G7PXMlT', 'Press Pallof vertical com elastico', array['Fique de pe com os pes na largura dos ombros e enrole o elastico em um objeto firme na altura do peito', 'Segure o elastico com ambas as maos e afaste-se do ponto de ancoragem, criando tensao no elastico', 'Contraia o tronco e alinhe os punhos com os antebracos', 'Pressione o peso ou as manoplas para longe enquanto mantem o tronco contraido', 'Controle o elastico no caminho de volta em vez de deixar que ele o puxe de volta para a posicao', 'Desca o peso ate a altura inicial de forma controlada antes de pressionar novamente']),
  ('G7xoEzr', 'Elevacao alternada de pernas sentado com barra', array['Sente-se em um banco com as costas retas e segure uma barra sobre as coxas', 'Com as pernas esticadas, leve uma perna o mais alto possivel enquanto mantem a outra perna no chao', 'Contraia o abdomen e mantenha os ombros ancorados no apoio', 'Eleve as pernas contraindo o tronco e movimentando os quadril em vez de balancar', 'Termine o movimento de um lado antes que o outro lado comece', 'Desca as pernas devagar sem balancar ou perder a posicao do tronco; alterne os lados quando o exercicio exigir'])
